画面に出す文字だけを、お店の人の言葉にする例（サンプル予約・仮の例）
// 画面に出すラベルは、お店の人の言葉。URL や内部の名前は、作り手の言葉のままでよい
type MenuItem = { label: string; href: string };
type MenuGroup = { label: string; items: MenuItem[] };

export const ADMIN_MENU: MenuGroup[] = [
  {
    label: '毎日',
    items: [
      { label: '今日の予約を見る', href: '/admin/reservations/today' },
      { label: '予約を入れる・直す', href: '/admin/reservations' },
    ],
  },
  {
    label: '予約の受け方を変える',
    items: [
      { label: '受け付ける曜日と時間', href: '/admin/slots' }, // 内部では「枠」のまま
      { label: 'お休みの日', href: '/admin/slots/exceptions' }, // 内部では「例外日」
    ],
  },
  {
    label: 'お客さまとのやりとり',
    items: [
      { label: 'お客さまの一覧', href: '/admin/customers' },
      { label: '予約の確認メールの文面', href: '/admin/notification-templates' },
      { label: '予約の一覧を表で保存', href: '/admin/reservations/export' }, // 中身は CSV
    ],
  },
];

ステップの画面が入れ替わっても、読み込み直しても、同じタブの中なら入力が残る例（サンプル予約・仮の例）。連絡先は個人の情報なので、確定したとき・やめたときに消す
// 予約の入力を、ステップの外（このタブの中だけの保存場所）に持つ
type Draft = { date?: string; time?: string; name?: string; tel?: string; email?: string };

const KEY = 'sample-yoyaku:draft';

export const loadDraft = (): Draft => {
  try {
    return JSON.parse(sessionStorage.getItem(KEY) ?? '{}') as Draft;
  } catch {
    return {}; // 壊れていたら、空から始める
  }
};

// 入力が変わるたびに残す。確認の画面から戻ったら、ここから欄に入れ直す
export const saveDraft = (patch: Draft): void => {
  sessionStorage.setItem(KEY, JSON.stringify({ ...loadDraft(), ...patch }));
};

// 予約が確定したとき・やめたときに消す（共用の端末に連絡先を残さない）
export const clearDraft = (): void => {
  sessionStorage.removeItem(KEY);
};

大きさは rem、行間は単位なしの数で書く。余白は「まとまりの中」と「まとまりの間」の 2 つから始める
/* 文字の大きさは 3 段階（大・中・小）。差が足りないところは太さで付ける */
:root {
  --text-lg: 1.5rem;   /* 24px 見出し */
  --text-md: 1rem;     /* 16px 本文・小見出し */
  --text-sm: 0.875rem; /* 14px 補足・注 */
  --space-in: 0.5rem;  /* 8px まとまりの中（ラベルと欄など） */
  --space-out: 2rem;   /* 32px まとまりとまとまりの間 */
}
body { font-size: var(--text-md); line-height: 1.7; }
h1 { font-size: var(--text-lg); font-weight: 700; line-height: 1.4; }
h2 { font-size: var(--text-md); font-weight: 700; line-height: 1.5; }
.note { font-size: var(--text-sm); line-height: 1.6; }
.field { display: grid; gap: var(--space-in); }
.field + .field { margin-top: var(--space-out); }

WCAG 2.2 の定義をそのまま TypeScript にしたもの（動画の場面 6）。比は丸めずに基準と比べる
// 相対輝度（WCAG 2.2 の定義。色は sRGB の 0〜255）
const lin = (v: number) => {
  const s = v / 255;
  return s <= 0.04045 ? s / 12.92 : ((s + 0.055) / 1.055) ** 2.4;
};
const lum = ([r, g, b]: number[]) => 0.2126 * lin(r) + 0.7152 * lin(g) + 0.0722 * lin(b);

// コントラスト比 =（明るいほう + 0.05）÷（暗いほう + 0.05）
const ratio = (a: number[], b: number[]) => {
  const [hi, lo] = [lum(a), lum(b)].sort((x, y) => y - x);
  return (hi + 0.05) / (lo + 0.05);
};

// 丸めずに比べる（4.478… は 4.5 に届かない）
const passText = (fg: number[], bg: number[]) => ratio(fg, bg) >= 4.5;
passText([0x77, 0x77, 0x77], [255, 255, 255]); // false（4.478…）
passText([0x76, 0x76, 0x76], [255, 255, 255]); // true（4.542…）

改善案を試すためだけの 1 枚のページ。保存も送信もしない。スマホで開いて入力してもらう
<!-- 改善案を試すだけの 1 枚の HTML（保存も送信もしない） -->
<label for="tel">電話番号</label>
<p id="tel-hint">ハイフンはあってもなくても大丈夫です</p>
<input id="tel" type="tel" autocomplete="tel" aria-describedby="tel-hint">
<p id="tel-error" hidden>電話番号は、10 桁か 11 桁の数字で入れてください</p>
<button type="button" id="next">確認へ進む</button>
<script>
  document.getElementById('next').addEventListener('click', () => {
    const input = document.getElementById('tel');
    // 全角の数字は半角にし、ハイフンや空白は除いて桁を数える
    const digits = input.value.normalize('NFKC').replace(/\D/g, '');
    const ok = digits.length === 10 || digits.length === 11;
    document.getElementById('tel-error').hidden = ok;
    input.setAttribute('aria-invalid', String(!ok));
    input.setAttribute('aria-describedby', ok ? 'tel-hint' : 'tel-hint tel-error');
  });
</script>
